def projection(raw,present):
    pos=0;items=0;values=[];rebuilt=bytearray();counts={};cuts=set();extents=[]
    def scalar(t,emit=True):
        nonlocal pos
        fmt={'i':'<i','u':'<I','b':'<B','s':'<h'}[t];n=struct.calcsize(fmt)
        cuts.update((pos,pos+1,pos+n));v=struct.unpack_from(fmt,raw,pos)[0];pos+=n;rebuilt.extend(struct.pack(fmt,v))
        if emit:values.append(v)
        return v
    def read(t):
        nonlocal items
        start=pos
        if t in ('i','u','b','s'):return scalar(t)
        if t=='Coord':return [scalar('i'),scalar('i')]
        if t=='String':
            n=scalar('u');items+=n;return [scalar('b') for _ in range(n)]
        if t.startswith('['):
            n=scalar('u');items+=n
            if n>len(raw):raise ValueError('hostile count')
            return [read(t[1:-1]) for _ in range(n)]
        if t=='Fixed6':
            if scalar('u')!=6:raise ValueError('fixed6 count')
            items+=6;return [read('Coord') for _ in range(6)]
        if t=='Fixed64':
            if scalar('u')!=64:raise ValueError('fixed count')
            items+=64;return [scalar('i') for _ in range(64)]
        if t=='RecycledOperations':
            if scalar('u',False)!=0x10001 or scalar('u',False)!=16:raise ValueError('recycled version/block')
            capacity=scalar('u');entries=read('[OperationEntry]');current_id_bits=scalar('u');n=scalar('u');items+=n;first_free=scalar('u');last_free=scalar('u');free_indices=[scalar('u') for _ in range(n)]
            return dict(capacity=capacity,entries=entries,current_id_bits=current_id_bits,first_free=first_free,last_free=last_free,free_indices=free_indices)
        if t=='OperationTypes' and not present:return None
        version,fields=SCHEMAS[t];counts[t]=counts.get(t,0)+1
        if version is not None and scalar('u',False)!=version:raise ValueError('version '+t+' at '+str(start))
        value={name:read(kind) for name,kind in fields};extents.append((t,start,pos));return value
    value=read('Military')
    if pos!=len(raw) or rebuilt!=raw:raise ValueError('typed extent/repacking '+str(pos)+'/'+str(len(raw)))
    return value,items,values,counts,sorted(n for n in cuts if n<len(raw)),extents

def harness():
    out=['use c6_core::{unit::Limits,player_ai_military::*};',
         'fn mix(h:&mut u64,v:i64){for b in v.to_le_bytes(){*h=(*h^u64::from(b)).wrapping_mul(1099511628211)}}']
    def emit(t,e):
        if t=='b':return f'mix(h,({e}).0 as i64);'
        if t in ('i','u','s'):return f'mix(h,({e}) as i64);'
        if t=='Coord':return f'for v in &({e}){{mix(h,*v as i64)}}'
        if t=='Fixed6':return f'mix(h,6);for coord in &({e}).0{{for v in coord{{mix(h,*v as i64)}}}}'
        if t=='Fixed64':return f'mix(h,64);for v in &({e}).0{{mix(h,*v as i64)}}'
        if t=='String':return f'mix(h,({e}).0.len() as i64);for v in &({e}).0{{mix(h,*v as i64)}}'
        if t.startswith('['):return f'mix(h,({e}).len() as i64);for v in &({e}){{'+emit(t[1:-1],'*v')+'}'
        if t=='OperationTypes':return f'if let Some(v)=&({e}){{p_OperationTypes(v,h)}}'
        return f'p_{t}(&({e}),h);'
    for name,(_,fields) in SCHEMAS.items():
        out.append(f'#[allow(non_snake_case)] fn p_{name}(v:&{name},h:&mut u64){{'+''.join(emit(t,'v.'+f) for f,t in fields)+'}')
    out.append('''#[allow(non_snake_case)] fn p_RecycledOperations(v:&RecycledOperations,h:&mut u64){mix(h,v.capacity as i64);mix(h,v.entries.len() as i64);for v in &v.entries{p_OperationEntry(v,h)}mix(h,v.current_id_bits as i64);mix(h,v.free_indices.len() as i64);mix(h,v.first_free as i64);mix(h,v.last_free as i64);for v in &v.free_indices{mix(h,*v as i64)}}
fn main(){let args:Vec<_>=std::env::args().collect();let all=std::fs::read(&args[1]).unwrap();let mut at=0;let mut records=0;let mut digest=14695981039346656037u64;
while at<all.len(){let n=u32::from_le_bytes(all[at..at+4].try_into().unwrap()) as usize;at+=4;let raw=&all[at..at+n];at+=n;let context=Context{operation_type_arrays_present:true};let generous=Limits{max_bytes:n,max_items:n};let(v,used,items)=Military::decode_prefix_with_items_in_context(raw,generous,context).unwrap();assert_eq!(used,n);p_Military(&v,&mut digest);let exact=Limits{max_bytes:n,max_items:items};assert_eq!(Military::decode_in_context(raw,exact,context).unwrap(),v);assert_eq!(v.encode_with_items(exact).unwrap(),(raw.to_vec(),items));assert_eq!(Military::decode(raw,exact),Err(Error::MissingContext));
let cuts=u32::from_le_bytes(all[at..at+4].try_into().unwrap()) as usize;at+=4;for _ in 0..cuts{let end=u32::from_le_bytes(all[at..at+4].try_into().unwrap()) as usize;at+=4;assert!(end<n);assert!(Military::decode_in_context(&raw[..end],exact,context).is_err());}
for short in [Limits{max_bytes:n-1,..exact},Limits{max_items:items-1,..exact}]{assert_eq!(Military::decode_in_context(raw,short,context),Err(Error::ResourceLimit));assert_eq!(v.encode(short),Err(Error::ResourceLimit));}
let mut tail=raw.to_vec();tail.extend_from_slice(&[91;128]);assert_eq!(Military::decode_in_context(&tail,exact,context),Err(Error::Trailing));assert_eq!(Military::decode_prefix_with_items_in_context(&tail,exact,context).unwrap(),(v,n,items));records+=1;}assert_eq!(records,86);println!("{records} {digest}");}''')
