def candidate(pin,records,expected_digest):
    pin=subprocess.check_output(['git','rev-parse',pin+'^{commit}'],cwd=ROOT,text=True).strip()
    archive=subprocess.check_output(['git','archive',pin],cwd=ROOT);driver=Path(__file__).relative_to(ROOT)
    with tempfile.TemporaryDirectory(prefix='c6-ai-military-') as tmp:
        tmp=Path(tmp);source=tmp/'source';source.mkdir();subprocess.run(['tar','-x','-C',str(source)],input=archive,check=True)
        if (source/driver).read_bytes()!=Path(__file__).read_bytes():raise ValueError('driver not committed at pin')
        if 'pub mod player_ai_military;' not in (source/'crates/c6-core/src/lib.rs').read_text():raise ValueError('committed archive missing Military export')
        paths=subprocess.check_output(['git','ls-tree','-r','--name-only',pin],cwd=ROOT,text=True).splitlines();identities={}
        for path in paths:
            p=source/path
            if p.is_symlink():continue
            expected=subprocess.check_output(['git','show',pin+':'+path],cwd=ROOT)
            if p.read_bytes()!=expected:raise ValueError('archive source mismatch '+path)
            identities[path]=sha(expected)
        subprocess.run(['cargo','test','--offline','-p','c6-core','player_ai_military'],cwd=source,check=True)
        subprocess.run(['cargo','clippy','--offline','-p','c6-core','--all-targets','--','-D','warnings'],cwd=source,check=True)
