        harness_text=harness();(tmp/'main.rs').write_text(harness_text)
        subprocess.run(['rustc','--edition=2021','-Dwarnings','-O',str(tmp/'main.rs'),'--extern','c6_core='+str(source/'target/release/libc6_core.rlib'),'-L','dependency='+str(source/'target/release/deps'),'-o',str(tmp/'candidate')],check=True)
        (tmp/'records').write_bytes(records);count,digest=map(int,subprocess.check_output([str(tmp/'candidate'),str(tmp/'records')],text=True).split())
        if count!=86 or digest!=expected_digest:raise ValueError('independent typed projection mismatch')
        for path,digest_source in identities.items():
            if sha((source/path).read_bytes())!=digest_source:raise ValueError('source changed during build '+path)
